import React,{useState}from'react';import{createRoot}from'react-dom/client';import'./styles.css';
const tx=[['Coffee & snack','Food','₹180','Today'],['Metro top-up','Travel','₹420','Yesterday'],['Notebook set','Study','₹260','12 Oct'],['Movie night','Fun','₹350','10 Oct']];const cats=['Food','Travel','Study','Fun'];
function App(){const[tab,setTab]=useState('Overview'),[add,setAdd]=useState(false),[items,setItems]=useState(tx);return <main><header><div className="brand"><span className="logo">₹</span><div><b>Pocketwise</b><small>Student expense tracker</small></div></div><button className="avatar">AJ</button></header><section className="hero"><div><p className="eyebrow">OCTOBER 2024</p><h1>Money, made<br/><em>clear.</em></h1><p className="muted">You’re building good habits. Keep going.</p></div><button className="primary" onClick={()=>setAdd(true)}>＋ Add expense</button></section><nav className="tabs">{['Overview','Transactions','Goals'].map(x=><button className={tab===x?'selected':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav>{tab==='Overview'&&<><div className="stats"><div className="card"><span className="eyebrow">SPENT THIS MONTH</span><h2>₹4,820</h2><small>of ₹12,000 budget</small><div className="progress"><i style={{width:'40%'}}/></div></div><div className="card"><span className="eyebrow">LEFT TO SPEND</span><h2>₹7,180</h2><small>₹231 daily average</small><div className="spark">▁▂▂▃▅▆▅▇</div></div><div className="card"><span className="eyebrow">SAVING GOAL</span><h2>₹2,400</h2><small>New headphones · 60%</small><div className="progress"><i style={{width:'60%'}}/></div></div></div><section className="card transactions"><div className="sectiontitle"><h2>Recent transactions</h2><button onClick={()=>setTab('Transactions')}>View all →</button></div>{items.slice(0,4).map(x=><div className="transaction" key={x[0]}><span className="dot">{x[0][0]}</span><span><b>{x[0]}</b><small>{x[1]} · {x[3]}</small></span><strong>{x[2]}</strong></div>)}</section></>}{tab==='Transactions'&&<section className="card transactions"><h2>All transactions</h2>{items.map(x=><div className="transaction" key={x[0]}><span className="dot">{x[0][0]}</span><span><b>{x[0]}</b><small>{x[1]} · {x[3]}</small></span><strong>{x[2]}</strong></div>)}</section>}{tab==='Goals'&&<section className="card goal"><span className="eyebrow">SAVINGS GOAL</span><h2>New headphones</h2><p className="muted">₹2,400 of ₹4,000 saved</p><div className="progress large"><i style={{width:'60%'}}/></div><button className="primary">Add money</button></section>}{add&&<div className="modal"><div className="modalbox"><button className="close" onClick={()=>setAdd(false)}>×</button><span className="eyebrow">NEW TRANSACTION</span><h2>What did you spend?</h2><input placeholder="e.g. Lunch with friends" autoFocus/><input placeholder="Amount" type="number"/><button className="primary full" onClick={()=>{setAdd(false);setItems([['New expense','Other','₹0','Just now'],...items])}}>Save expense</button></div></div>}</main>}createRoot(document.getElementById('root')).render(<App/>);
